const t=document.getElementById("stars"),o=t.getContext("2d");function r(){t.width=window.innerWidth,t.height=window.innerHeight;const e=Math.floor(t.width*.12);return Array.from({length:e},()=>({x:Math.random()*t.width,y:Math.random()*t.height,z:Math.random()*t.width,radius:Math.random()*.8+.2}))}let c=r();function f(i){i.x=Math.random()*t.width,i.y=Math.random()*t.height,i.z=t.width,i.radius=Math.random()*.8+.2}function m(){o.clearRect(0,0,t.width,t.height);const i=t.width/2,e=t.height/2;c.forEach(n=>{const d=n.x-i,h=n.y-e,s=t.width/(t.width+n.z),a=i+d*s,u=e+h*s,y=n.radius*s*2;o.beginPath(),o.arc(a,u,y,0,Math.PI*2),o.fillStyle="white",o.shadowBlur=6,o.shadowColor="white",o.fill()})}function l(){const i=t.width/2,e=t.height/2;c.forEach(n=>{const d=n.x-i,h=n.y-e,a=5+Math.sqrt(d*d+h*h)/480;n.z-=a,n.z<=1&&f(n)})}function g(){c=r()}window.addEventListener("resize",g);function w(){m(),l(),requestAnimationFrame(w)}w();
